let seed,mySize;
let angle_c;
let colors = [];
let colors7 = "ff00ff-00aaff-00eeee-ff0000-ffaa00".split("-").map((a) => "#" + a);
let colors8 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
var color_setup1,color_setup2;
let color_bg;
let branch;

function setup() {
	// pixelDensity(5);
	mySize = min(1112, 834);
	createCanvas(1112, 834);
	seed = int(random(1000));
	colorMode(HSB, 360, 100, 100, 100);
	color_setup1 = colors7;
	color_setup2 = colors8;
	color_bg = "#000000";
	background(color_bg);
	angle_c = 0;
	branch = int(random(4,20));
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

	randomSeed(seed);
	drawingContext.shadowColor = str(random(color_setup1)) + "00";
	drawingContext.shadowOffsetX = 0;
	drawingContext.shadowOffsetY = 0;
	drawingContext.shadowBlur = 0;
	translate(width / 2, height / 2);
	rotate(angle_c);
	for (let i = 0; i < 2; i++) {
		colors[0] = random(color_setup1);
		colors[1] = random(color_setup1);
		colors[2] = random(color_setup1);
		colors[3] = random(color_setup1);
		colors[4] = random(color_setup2);
		circleForm(0, 0, mySize * 0.8 * (i + 1)/2);
	}
	if(frameCount % 100 == 0 && branch<1000) {
		branch += 10;
		angle_c += TAU/360;
	}else if(branch>= 1000){
		branch = 4;
		frameCount = 0;
	}
}

function circleForm(x, y, d) {


	let ang = TAU / branch;
	let angles = [];
	for (let i = 0; i < branch; i++) {
		angles.push(ang * (i + iteration(0.1, 0.25)));
	}
	for (let i = 0; i < branch; i++) {
		let ang1 = angles[i];
		let ang2 = angles[(i + int(random(6))) % angles.length];
		let dd = d * iteration(0.1, 1);
		noFill();
		drawingContext.shadowColor = random(color_setup1);
		drawingContext.shadowOffsetX = 1;
		drawingContext.shadowOffsetY = 1;
		drawingContext.shadowBlur = 0;
		stroke(colors[random([0,1,2,3,4])]);
		strokeWeight(random(1));
		arc(x, y, dd, dd, ang1, ang2);
	}
}

function iteration(s, e) {
	let t = random(10, 100);
	let v = random(0.001, 0.01);
	return map(cos(t + frameCount * v), -1, 1, s, e);
}

function keyTyped() {
	saveCanvas("NoisePlanet_ALPHA_2022", "png");
}

//fullscreen
function mousePressed() {
  if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) {
    let fs = fullscreen();
    fullscreen(!fs);
  }
}

